-- Canonical units only (PREF-06): ml, fraction ABV, UTC timestamps in ms, g/L.
-- Opaque ids everywhere (SEC-02): UUIDs generated by clients for their own writes, by the server otherwise.

create table users (
  id uuid primary key,
  username text not null unique,
  display_name text not null,
  created_at bigint not null
);

create table sessions (
  token_hash text primary key,
  user_id uuid not null references users(id) on delete cascade,
  device_label text not null default '',
  created_at bigint not null,
  last_seen_at bigint not null
);
create index sessions_user on sessions(user_id);

create table transfer_codes (
  code_hash text primary key,
  user_id uuid not null references users(id) on delete cascade,
  expires_at bigint not null
);

create table user_preferences (
  user_id uuid primary key references users(id) on delete cascade,
  data text not null,
  updated_at bigint not null
);

-- Weight and body model are health data (SEC-08): the row holds ciphertext only.
create table body_profiles (
  user_id uuid primary key references users(id) on delete cascade,
  sealed text not null,
  updated_at bigint not null
);

create table drinks (
  id uuid primary key,
  user_id uuid not null references users(id) on delete cascade,
  party_id uuid,
  kind text not null,
  preset_id text not null,
  sealed text not null,
  consumed_at bigint not null,
  logged_at bigint not null,
  verified boolean not null default false,
  deleted_at bigint,
  updated_at bigint not null
);
create index drinks_user_time on drinks(user_id, consumed_at);
create index drinks_party on drinks(party_id);

create table water (
  id uuid primary key,
  user_id uuid not null references users(id) on delete cascade,
  party_id uuid,
  at bigint not null,
  deleted_at bigint,
  updated_at bigint not null
);
create index water_user_time on water(user_id, at);

create table custom_drinks (
  id uuid primary key,
  user_id uuid not null references users(id) on delete cascade,
  data text not null,
  deleted_at bigint,
  updated_at bigint not null
);
create index custom_drinks_user on custom_drinks(user_id);

create table crews (
  id uuid primary key,
  name text not null,
  created_by uuid not null references users(id),
  created_at bigint not null
);

create table crew_members (
  crew_id uuid not null references crews(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  role text not null check (role in ('admin', 'member')),
  nickname text,
  joined_at bigint not null,
  primary key (crew_id, user_id)
);
create index crew_members_user on crew_members(user_id);

create table crew_invites (
  code text primary key,
  crew_id uuid not null references crews(id) on delete cascade,
  created_by uuid not null references users(id),
  expires_at bigint not null,
  uses integer not null default 0
);

create table parties (
  id uuid primary key,
  crew_id uuid not null references crews(id) on delete cascade,
  name text not null,
  mood text not null,
  kind text not null check (kind in ('party', 'trip')),
  starts_at bigint not null,
  ends_at bigint not null,
  closed_at bigint,
  created_by uuid not null references users(id),
  created_at bigint not null
);
create index parties_crew_time on parties(crew_id, starts_at);

create table party_members (
  party_id uuid not null references parties(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  response text not null check (response in ('invited', 'going', 'declined')),
  designated_driver boolean not null default false,
  home_safe_at bigint,
  last_activity_at bigint,
  battery_low boolean not null default false,
  primary key (party_id, user_id)
);
create index party_members_user on party_members(user_id);

-- Stored answers for idempotency keys (SYNC-01, AC-08): a replay gets the same answer.
create table mutation_log (
  key text not null,
  user_id uuid not null references users(id) on delete cascade,
  result text not null,
  created_at bigint not null,
  primary key (user_id, key)
);
